// Firebase service for form submissions
import {
  collection,
  doc,
  getDocs,
  getCountFromServer,
  limit,
  orderBy,
  query,
  serverTimestamp,
  setDoc,
  updateDoc,
  where,
  writeBatch,
} from 'firebase/firestore';
import { getDownloadURL, ref, uploadBytes } from 'firebase/storage';
import { db, storage } from '../firebase/config';

const COLLECTION_NAME = 'formSubmissions';

const submissionErrorMessage = (code, stage) => {
  if (['storage/bucket-not-found', 'storage/project-not-found', 'storage/no-default-bucket'].includes(code)) {
    return 'CV storage is not available yet. Your information has not been submitted.';
  }
  if (code === 'permission-denied' || code === 'storage/unauthorized') {
    return stage === 'upload-cv'
      ? 'Your CV could not be uploaded because access was denied. Your information has not been submitted.'
      : 'Your submission could not be saved because access was denied. Please try again later.';
  }
  if (code === 'storage/unauthenticated' || code === 'unauthenticated') {
    return 'Please sign in again before submitting your information.';
  }
  if (code === 'storage/quota-exceeded') return 'CV storage is temporarily unavailable. Please try again later.';
  if (code === 'unavailable' || code === 'storage/retry-limit-exceeded') {
    return 'We couldn’t connect to save your information. Please check your connection and try again.';
  }
  return stage === 'finalize-submission'
    ? 'Your CV was uploaded, but we couldn’t finish saving your submission. Please try again.'
    : 'We couldn’t save your submission. Please try again.';
};

// Create a tracked submission and keep the CV in Firebase Storage.
export const submitForm = async (formData, cvFile, userId) => {
  if (!userId) return { success: false, code: 'unauthenticated', stage: 'validate', message: 'Please sign in before submitting.' };
  if (!cvFile || !/\.(pdf|doc|docx)$/i.test(cvFile.name) || cvFile.size > 5 * 1024 * 1024) {
    return { success: false, code: 'invalid-cv', stage: 'validate', message: 'Please choose one PDF, DOC, or DOCX file up to 5 MB.' };
  }
  let submissionRef;
  let created = false;
  let stage = 'create-submission';
  try {
    submissionRef = doc(collection(db, COLLECTION_NAME));
    await setDoc(submissionRef, {
      ...formData,
      userId,
      status: 'uploading',
      cvPath: null,
      cvUrl: null,
      submittedAt: null,
      updatedAt: serverTimestamp(),
    });

    created = true;
    stage = 'upload-cv';
    const extension = cvFile.name.split('.').pop().toLowerCase();
    const contentType = {
      pdf: 'application/pdf',
      doc: 'application/msword',
      docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    }[extension];
    const cvPath = `cvs/${userId}/${submissionRef.id}/cv.${extension}`;
    const cvRef = ref(storage, cvPath);
    await uploadBytes(cvRef, cvFile, { contentType });
    stage = 'get-cv-url';
    const cvUrl = await getDownloadURL(cvRef);

    stage = 'finalize-submission';
    const historyRef = doc(collection(submissionRef, 'statusHistory'));
    const batch = writeBatch(db);
    batch.update(submissionRef, {
      cvPath,
      cvUrl,
      cvName: cvFile.name,
      cvSize: cvFile.size,
      cvType: contentType,
      status: 'submitted',
      submittedAt: serverTimestamp(),
      updatedAt: serverTimestamp(),
    });
    batch.set(historyRef, {
      status: 'submitted',
      note: 'Submission received.',
      changedBy: userId,
      changedAt: serverTimestamp(),
    });
    await batch.commit();

    return { 
      success: true, 
      id: submissionRef.id,
      message: 'Form submitted successfully!' 
    };
  } catch (error) {
    if (created) {
      try {
        await updateDoc(submissionRef, {
          status: 'upload_failed',
          updatedAt: serverTimestamp(),
        });
      } catch (statusError) {
        console.error('Error recording failed submission:', statusError);
      }
    }
    console.error('Error submitting form:', { stage, code: error.code, message: error.message });
    return { 
      success: false, 
      code: error.code || 'unknown',
      stage,
      message: submissionErrorMessage(error.code, stage) 
    };
  }
};

export const updateSubmissionStatus = async ({ submissionId, status, adminId, note = '' }) => {
  const submissionRef = doc(db, COLLECTION_NAME, submissionId);
  const historyRef = doc(collection(submissionRef, 'statusHistory'));
  const batch = writeBatch(db);

  batch.update(submissionRef, { status, updatedAt: serverTimestamp() });
  batch.set(historyRef, {
    status,
    note,
    changedBy: adminId,
    changedAt: serverTimestamp(),
  });

  await batch.commit();
  return { success: true, message: 'Submission status updated.' };
};

export const getSubmissionStatusHistory = async submissionId => {
  const historyQuery = query(
    collection(db, COLLECTION_NAME, submissionId, 'statusHistory'),
    orderBy('changedAt', 'desc')
  );
  const snapshot = await getDocs(historyQuery);
  return snapshot.docs.map(historyDoc => ({ id: historyDoc.id, ...historyDoc.data() }));
};

// Fetch only this user's history. Sort locally to avoid requiring a composite index.
export const getUserFormSubmissions = async (userId) => {
  if (!userId) return { success: false, message: 'Sign in to view submissions' };
  try {
    const snapshot = await getDocs(query(
      collection(db, COLLECTION_NAME),
      where('userId', '==', userId)
    ));
    const data = snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id }));
    data.sort((a, b) => (b.submittedAt?.seconds || 0) - (a.submittedAt?.seconds || 0));
    return { success: true, data };
  } catch (error) {
    console.error('Error fetching your submissions:', error.code, error.message);
    return { success: false, code: error.code, message: error.code === 'permission-denied'
      ? 'Your submission history could not be accessed. Please try again later.'
      : 'Your submission history isn’t available right now. You can try refreshing.' };
  }
};

// Get all form submissions (for admin viewing)
export const getFormSubmissions = async (limitCount = 50) => {
  try {
    const q = query(
      collection(db, COLLECTION_NAME), 
      orderBy('submittedAt', 'desc'), 
      limit(limitCount)
    );

    const querySnapshot = await getDocs(q);
    const submissions = [];

    querySnapshot.forEach((doc) => {
      submissions.push({
        id: doc.id,
        ...doc.data()
      });
    });

    return { 
      success: true, 
      data: submissions 
    };
  } catch (error) {
    console.error('Error fetching submissions:', error);
    return { 
      success: false, 
      message: 'Failed to fetch submissions' 
    };
  }
};

// Get form submission count
export const getSubmissionCount = async () => {
  try {
    const countSnapshot = await getCountFromServer(collection(db, COLLECTION_NAME));
    return { 
      success: true, 
      count: countSnapshot.data().count
    };
  } catch (error) {
    console.error('Error getting submission count:', error);
    return { 
      success: false, 
      message: 'Failed to get submission count' 
    };
  }
};

const firebaseService = {
  submitForm,
  getFormSubmissions,
  getSubmissionCount,
  updateSubmissionStatus,
  getSubmissionStatusHistory,
};

export default firebaseService;
